        //         "MT": "0",
        //         "NV": "--",
        //         "t": "1731135533126"
        //     }
        //
        let mut marketId: Value = self.safe_string_k(ticker.clone(), "s", &[]);
        let mut timestamp: Value = self.safe_integer_k(ticker.clone(), "t", &[]);
